'use client'
import { useEffect, useRef, useState, type ReactNode } from 'react'
import { cn } from '@/lib/cn'
import { CellBurst } from '@/components/visuals/CellBurst'
import { Grain } from '@/components/visuals/Grain'
import { useSeen } from '@/hooks/useCellBurst'

// A blog post as a card (BlogCard.vue): in its own ruled box, which takes the paper under the pointer, a picture (a
// grained dark panel and a jumbled sheet of cells) with the category in red at its top right, then the title, its
// line, and at the foot, each in a ruled tag, who it is from and the date. `window` (Vue's `#window` scoped slot) is
// what plays in the picture once the card is on screen (the website puts a benchmark's leaderboard there, an EvalViz,
// which is stretched to the box): it is laid out at one size on every card, 520 by 380, and scaled as a whole to fit,
// so every card's window matches and none reflows. It gets `active` once 40% of the picture is on screen and stays
// hidden, not blank, until then.
export interface BlogCardProps {
  href: string
  title: string
  dek?: string
  category: string
  author?: string
  date?: string
  seed?: number
  /** What plays in the picture, given `active` once the card is on screen. */
  window?: (slot: { active: boolean }) => ReactNode
}

const VIZ_W = 520
const VIZ_H = 380

export function BlogCard({ href, title, dek, category, author, date, seed, window: win }: BlogCardProps) {
  const art = useRef<HTMLSpanElement | null>(null)
  const seen = useSeen(art, 0.4)
  const burstSeed = seed ?? 71 + title.length * 13
  const [fit, setFit] = useState(0.7)
  useEffect(() => {
    const observer = new ResizeObserver(([entry]) => {
      const { width, height } = entry!.contentRect
      setFit(Math.min((width * 0.88) / VIZ_W, (height * 0.88) / VIZ_H))
    })
    if (art.current) observer.observe(art.current)
    return () => observer.disconnect()
  }, [])
  return (
    <>
      <style href="ds-blog-card" precedence="ds">{css}</style>
      <a data-ds="blog-card" href={href} className="ds-blog-card flex w-full flex-col border border-edge p-2">
        <span ref={art} aria-hidden="true" className="relative grid aspect-[5/4] grid-cols-[minmax(0,1fr)] place-items-center overflow-hidden bg-ds-neutral-200 px-4 text-ds-neutral-300">
          <Grain />
          <span className="ds-blog-tag absolute top-2.5 right-2.5 z-1 bg-home-red py-0.5 pl-0.75 text-tag-sm font-medium tracking-tag text-off-white">{category}</span>
          <span className="pointer-events-none absolute inset-0 opacity-70"><CellBurst seed={burstSeed} jumble /></span>
          {win && (
            <span
              className={cn('absolute top-1/2 left-1/2 flex [&>.ds-viz]:h-full [&>.ds-viz]:max-w-none [&>.ds-viz>.ds-viz-card]:h-full', !seen && 'invisible')}
              style={{ width: `${VIZ_W}px`, height: `${VIZ_H}px`, transform: `translate(-50%, -50%) scale(${fit})` }}
            >
              {win({ active: seen })}
            </span>
          )}
        </span>
        <span className="mt-4 block px-2 text-card-title text-fg">{title}</span>
        {dek && <span className="mt-2 block px-2 text-body leading-5.5 text-fg-muted">{dek}</span>}
        {(author || date) && (
          <span className="mt-auto flex items-center justify-between gap-4 px-2 pt-6 pb-2 type-meta text-fg-faint">
            {author && <span className="border border-edge px-1.5 leading-5">{author}</span>}
            {date && <span className="ml-auto border border-edge px-1.5 leading-5 tabular-nums">{date}</span>}
          </span>
        )}
      </a>
    </>
  )
}

export default BlogCard

const css = `
.ds-blog-card { transition: background-color var(--ds-duration-micro) var(--ds-easing-standard); }
@media (hover: hover) and (pointer: fine) { .ds-blog-card:hover { background-color: var(--ds-color-surface-subtle); } }
/* The category, in the section tag's red and capitals: 3px in, less the tracking on the right. */
.ds-blog-tag { padding-right: calc(var(--ds-space-xs) - 1px - var(--ds-tracking-tag)); line-height: var(--ds-text-tag-sm-leading); text-transform: uppercase; }
`

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

'use client'
import { useEffect, useState, type RefObject } from 'react'

// The "infinite cells" geometry behind the website's art (CellBurst, Burst): a level rectangle redrawn smaller and
// smaller as it recedes to a vanishing point at the origin, plus the seeded random source that keeps server and client
// drawing the same thing, and the two viewport helpers the art waits on.

/** A seeded random source (mulberry32), so server and client paths match. */
export function rng(seed: number) {
  let s = seed >>> 0
  return () => {
    s = (s + 0x6D2B79F5) >>> 0
    let t = s
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

// Paths are joined with + rather than template strings: the registry's class check reads a path command followed by
// an interpolation as a class glued to one.
const r1 = (n: number) => Math.round(n * 10) / 10

/**
 * One cell: the face at (x0, y0), w by h, relative to the vanishing point, with its copies `pitch` apart on screen
 * until they reach `inner` of the face's distance. `fill` is the slab's ground, laid under it so it hides what lies
 * behind; `lines` is the hatch.
 */
export function cellPaths(x0: number, y0: number, w: number, h: number, pitch: number, inner: number) {
  // The ground: copies stepping back by a constant fraction, which overlap into one solid shape.
  const dist = Math.hypot(x0 + w / 2, y0 + h / 2)
  const step = 1 - pitch / dist
  let fill = ''
  for (let s = 1; s > inner; s *= step) fill += 'M' + r1(x0 * s) + ' ' + r1(y0 * s) + 'h' + r1(w * s) + 'v' + r1(h * s) + 'h' + r1(-w * s) + 'z'
  // The hatch: each edge redrawn as it recedes, at its own step, so its copies land `pitch` apart all the way in.
  let lines = ''
  const edges = [
    { c: y0, a: x0, len: w, level: true },
    { c: y0 + h, a: x0, len: w, level: true },
    { c: x0, a: y0, len: h, level: false },
    { c: x0 + w, a: y0, len: h, level: false },
  ]
  for (const e of edges) {
    const ds = pitch / Math.abs(e.c)
    for (let s = 1; s > inner; s -= ds) lines += e.level ? 'M' + r1(e.a * s) + ' ' + r1(e.c * s) + 'h' + r1(e.len * s) : 'M' + r1(e.c * s) + ' ' + r1(e.a * s) + 'v' + r1(e.len * s)
  }
  return { fill, lines }
}

/** Halftone squares: dots 4px apart in blocks of 3 by 3, each block one size, growing towards one top corner. */
export const HALFTONE_DOT = 4
export const HALFTONE_BLOCK = 3
const LEVELS = [0.25, 0.45, 0.7, 0.95]
const r2 = (n: number) => Math.round(n * 100) / 100

export function halftone(x: number, y: number, size: number, left: boolean, rand: () => number) {
  const n = Math.max(HALFTONE_BLOCK, Math.floor(size / HALFTONE_DOT))
  const blocks = Math.ceil(n / HALFTONE_BLOCK)
  const tone = Array.from({ length: blocks * blocks }, () => rand())
  let dots = ''
  for (let row = 0; row < n; row++) {
    for (let col = 0; col < n; col++) {
      const across = left ? 1 - col / n : col / n
      const lean = (across + (1 - row / n)) / 2
      const t = tone[Math.floor(row / HALFTONE_BLOCK) * blocks + Math.floor(col / HALFTONE_BLOCK)]!
      const level = LEVELS[Math.min(LEVELS.length - 1, Math.floor((lean * 0.6 + t * 0.4) * LEVELS.length))]!
      const r = (HALFTONE_DOT / 2) * level
      const cx = x + (col + 0.5) * HALFTONE_DOT
      const cy = y + (row + 0.5) * HALFTONE_DOT
      dots += 'M' + r2(cx - r) + ' ' + r2(cy - r) + 'h' + r2(2 * r) + 'v' + r2(2 * r) + 'h' + r2(-2 * r) + 'z'
    }
  }
  const side = n * HALFTONE_DOT
  return { square: 'M' + r2(x) + ' ' + r2(y) + 'h' + side + 'v' + side + 'h' + -side + 'z', dots }
}

/** True once `el` comes within `margin` of the viewport, and from then on. Never on the server. */
export function useNearView(el: RefObject<Element | null>, margin = '400px') {
  const [near, setNear] = useState(false)
  useEffect(() => {
    if (!el.current || !('IntersectionObserver' in window)) {
      setNear(true)
      return
    }
    const io = new IntersectionObserver(([e]) => {
      if (!e?.isIntersecting) return
      setNear(true)
      io.disconnect()
    }, { rootMargin: margin })
    io.observe(el.current)
    return () => io.disconnect()
  }, []) // eslint-disable-line react-hooks/exhaustive-deps
  return near
}

/** True once `threshold` of `el` has been on screen, and from then on: a window that plays once. */
export function useSeen(el: RefObject<Element | null>, threshold = 0.2) {
  const [seen, setSeen] = useState(false)
  useEffect(() => {
    if (!el.current || !('IntersectionObserver' in window)) {
      setSeen(true)
      return
    }
    const io = new IntersectionObserver(([e]) => {
      if (!e?.isIntersecting) return
      setSeen(true)
      io.disconnect()
    }, { threshold })
    io.observe(el.current)
    return () => io.disconnect()
  }, []) // eslint-disable-line react-hooks/exhaustive-deps
  return seen
}
